cat > /tmp/spec.pl <<'EOF'
use strict; use warnings;

sub spec {
  my ($url) = @_;
  my ($scheme,$host,$port,$path,$query) = ('','',-1,'','');
  my $rest = $url;
  my $hp = index($rest, "#");
  if ($hp >= 0) { $rest = substr($rest,0,$hp); }
  my $qp = index($rest, "?");
  if ($qp >= 0) { $query = substr($rest,$qp+1); $rest = substr($rest,0,$qp); }
  my $sp = index($rest, "://");
  if ($sp < 0) { $path = $rest; return ($scheme,$host,$port,$path,$query); }
  $scheme = substr($rest,0,$sp);
  $scheme =~ tr/A-Z/a-z/;
  $rest = substr($rest,$sp+3);
  my $auth;
  my $sl = index($rest,"/");
  if ($sl >= 0) { $auth = substr($rest,0,$sl); $path = substr($rest,$sl); }
  else { $auth = $rest; $path = ''; }
  my $at = index($auth,"\@");
  if ($at >= 0) { $auth = substr($auth,$at+1); }
  my $co = index($auth,":");
  if ($co < 0) { $host = $auth; return ($scheme,$host,$port,$path,$query); }
  $host = substr($auth,0,$co);
  my $ps = substr($auth,$co+1);
  # stoi prefix parse
  my $i = 0;
  my @c = split //, $ps;
  while ($i < @c && $c[$i] =~ /^[\t\n\x0b\f\r ]$/) { $i++ }
  my $neg = 0;
  if ($i < @c && ($c[$i] eq '+' || $c[$i] eq '-')) { $neg = ($c[$i] eq '-'); $i++ }
  if ($i >= @c || $c[$i] !~ /^[0-9]$/) { return ($scheme,$host,-1,$path,$query); }
  my $mag = '';
  while ($i < @c && $c[$i] =~ /^[0-9]$/) { $mag .= $c[$i]; $i++ }
  $mag =~ s/^0+(?=\d)//;
  my $v;
  if (length($mag) > 18) { $v = undef }  # definitely out of range
  else { $v = 0 + $mag; $v = -$v if $neg; }
  if (!defined($v) || $v < 0 || $v > 65535) { return ($scheme,$host,-1,$path,$query); }
  return ($scheme,$host,$v,$path,$query);
}

sub run {
  my ($url) = @_;
  my $pid = open(my $fh, "-|");
  die "fork" unless defined $pid;
  if ($pid == 0) { exec("/workspace/dataset/test5_executable", $url) or exit 127; }
  local $/; my $out = <$fh>; $out = '' unless defined $out; close $fh;
  return $out;
}

sub esc { my $s = shift; $s =~ s/([^\x20-\x7e])/sprintf("\\x%02X",ord($1))/ge; return $s }

my @inputs;
if (@ARGV && $ARGV[0] eq '-') { while (my $l = <STDIN>) { chomp $l; push @inputs, $l } }
else { @inputs = @ARGV }

my $bad = 0; my $n = 0;
for my $u (@inputs) {
  next if $u =~ /\x00/;
  $n++;
  my @e = spec($u);
  my $expect = join("\n", @e) . "\n";
  my $got = run($u);
  if ($got ne $expect) {
    $bad++;
    print "DIVERGE input=[", esc($u), "]\n";
    print "  spec: ", esc($expect =~ s/\n/ | /gr), "\n";
    print "  real: ", esc($got    =~ s/\n/ | /gr), "\n";
  }
}
print "checked=$n diverge=$bad\n";
EOF
